"""Readable, self-contained presentation for the saved V3 evidence bundle."""
import base64
import html
import json
from datetime import datetime
from zoneinfo import ZoneInfo


def render_report(*, out, data, complete, metrics, figures, insights, notes, coverage, checks, table, detail_tables, norm):
    esc = html.escape
    names = {'single_without_past': '1 agent · No Past', 'single_with_past': '1 agent · Past',
             'swarm_without_past': '5 agents · No Past', 'swarm_with_past': '5 agents · Past'}
    colors = ['#0072B2', '#56B4E9', '#D55E00', '#009E73']
    def image(name):
        return 'data:image/png;base64,' + base64.b64encode((out / 'plots' / (name + '.png')).read_bytes()).decode()
    def gallery(indices):
        result = ''
        for i in indices:
            name, title, caption = figures[i]
            result += f'''<details class="figure-detail"><summary>{esc(title)}<span>View figure</span></summary>
            <p class="caption">{esc(caption)}</p><div class="figure-scroll"><button class="zoom" data-title="{esc(title)}" aria-label="Enlarge {esc(title)}"><img loading="lazy" src="{image(name)}" alt="{esc(title)}"></button></div>
            <p class="downloads"><span>Click the figure to enlarge.</span> <a href="plots/{name}.png">Download PNG</a>''' + (f' <a href="plots/{name}.svg">Download SVG</a>' if (out/'plots'/f'{name}.svg').exists() else '') + '</p></details>'
        return result
    investigation = '<p><a class="jump" href="behavior.html">Read the swarm behavior investigation and next-experiment recommendations →</a></p>' if (out/'behavior.html').exists() else ''
    cards = ''
    for i, m in enumerate(metrics):
        cards += f'''<article class="result" style="--series:{colors[i]}"><h3>{names[m['condition']]}</h3><div class="score">${m['net_usd_per_year']/1e9:.2f}<small>B / year</small></div><p>Best valid annual net value</p><dl><div><dt>Team queries</dt><dd>{m['queries']:,} / {m['allocation']:,}</dd></div><div><dt>Model spend</dt><dd>${m['model_usd']:.2f}</dd></div><div><dt>Elapsed time</dt><dd>{m['wall_minutes']:.1f} min</dd></div></dl></article>'''
    metric_fields = [('Annual revenue', 'revenue_usd_per_year', lambda v:f'${v/1e9:.2f}B'),('Annualized plant cost', 'annualized_cost_usd',lambda v:f'${v/1e9:.2f}B'),('Annual net value','net_usd_per_year',lambda v:f'${v/1e9:.2f}B'),('Ideal revenue ceiling attained','ceiling_fraction',lambda v:f'{v:.1%}'),('Physical columns','physical_column_units',str),('Double-effect positions','double_effect_columns',str),('Integrated heat','heat_integrated_MW',lambda v:f'{v:.1f} MW')]
    def comparison(fields):
        s='<div class="table" tabindex="0" aria-label="Comparison table; scroll horizontally on narrow screens"><table><thead><tr><th>Metric</th>'+''.join('<th>'+names[m['condition']]+'</th>' for m in metrics)+'</tr></thead><tbody>'
        for label,key,fmt in fields:
            s+='<tr><th scope="row">'+label+'</th>'+''.join('<td>'+fmt(m[key])+'</td>' for m in metrics)+'</tr>'
        return s+'</tbody></table></div>'
    search_fields=[('Charged queries','queries',lambda v:f'{v:,}'),('Actual backend calls','backend_calls',lambda v:f'{v:,}'),('Submitted attempts','attempts',lambda v:f'{v:,}'),('Invalid attempts','invalid_attempts',lambda v:f'{v:,}'),('Input tokens','input_tokens',lambda v:f'{v/1e6:.2f}M'),('Output tokens','output_tokens',lambda v:f'{v/1e3:.0f}K'),('Model requests','requests',lambda v:f'{v:,}')]
    series=[dict(name=names[r['config']['condition']], color=colors[i], dashed=i%2==1, points=r['curve']) for i,r in enumerate(complete)]
    legend=''.join(f'<span><i style="background:{colors[i]}"></i>{names[r["config"]["condition"]]}</span>' for i,r in enumerate(complete))
    cov=''.join(f'<tr><th scope="row">{esc(a)}</th><td>{esc(b)}</td><td>{esc(c)}</td></tr>' for a,b,c in coverage)
    appendices=''.join(f'<details><summary>{esc(title)}</summary>{content}</details>' for title,content in detail_tables)
    stamp=datetime.fromtimestamp(data['captured_at'],ZoneInfo('America/Los_Angeles')).strftime('%b %d, %Y · %I:%M %p PST')
    passed=sum(c['passed'] for c in checks)
    css='''
:root{--ink:#182b3b;--muted:#536573;--line:#dce4e9;--paper:#fff;--ground:#f5f7f9;--accent:#006c9c}*{box-sizing:border-box}body{margin:0;background:var(--ground);color:var(--ink);font:17px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:var(--accent);text-underline-offset:3px}button,select{font:inherit}button,a,summary,select{-webkit-tap-highlight-color:transparent}button,summary,select{cursor:pointer}:focus-visible{outline:3px solid #008ecb;outline-offset:4px}header,main,.nav-inner{max-width:1160px;margin:auto}header{padding:48px 32px 28px}.eyebrow{font-size:12px;font-weight:750;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}h1{font-size:clamp(30px,4vw,44px);letter-spacing:-.035em;line-height:1.12;margin:12px 0}header p{margin:12px 0 0;color:var(--muted);max-width:750px}.snapshot{font-size:13px}nav{position:sticky;top:0;z-index:5;background:#fff;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.nav-inner{display:flex;gap:28px;padding:0 32px;overflow:auto}nav a{white-space:nowrap;display:block;padding:16px 0;color:var(--muted);font-size:15px;font-weight:650;text-decoration:none;border-bottom:3px solid transparent}nav a[aria-current=page]{color:var(--ink);border-color:var(--accent)}nav a:hover{color:var(--accent)}main{padding:32px 32px 64px}.panel{scroll-margin-top:85px}.panel[hidden]{display:none}.section-title{font-size:28px;line-height:1.25;letter-spacing:-.025em;margin:0 0 12px}.lead{font-size:20px;line-height:1.5;max-width:830px;margin:0 0 28px}.muted,.caption{color:var(--muted)}.results{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:28px 0}.result{border:1px solid var(--line);border-top:4px solid var(--series);background:white;padding:20px;border-radius:5px}.result h3{font-size:16px;margin:0 0 14px}.score{font-size:34px;font-weight:700;letter-spacing:-.04em;white-space:nowrap}.score small{font-size:13px;letter-spacing:0;font-weight:500;margin-left:4px}.result p{font-size:12px;color:var(--muted);margin:0 0 20px}dl{margin:0;font-size:13px}dl div{display:flex;justify-content:space-between;gap:8px;margin-top:8px}dt{color:var(--muted)}dd{margin:0;font-variant-numeric:tabular-nums;font-weight:600}.findings{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px;margin:34px 0}.finding{border-top:1px solid var(--line);padding-top:18px}.finding h3{font-size:18px;line-height:1.4;margin:0 0 8px}.finding p{font-size:15px;margin:0;color:var(--muted)}.callout{border-left:3px solid #a77613;background:#fff9eb;padding:16px 20px;font-size:14px;max-width:900px}.block{background:var(--paper);border:1px solid var(--line);padding:28px;margin:24px 0;border-radius:6px}.block h3{margin:0 0 12px;font-size:21px;line-height:1.4}.block>p{max-width:850px}.jump{display:inline-block;margin-top:18px;font-weight:650}.chart-header{display:flex;justify-content:space-between;align-items:start;gap:24px;flex-wrap:wrap}.controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:8px 0 14px;font-size:14px}select{max-width:100%;background:white;border:1px solid #b3c1ca;border-radius:4px;padding:9px 32px 9px 12px;color:var(--ink)}.legend{display:flex;gap:12px 22px;flex-wrap:wrap;font-size:13px;margin:8px 0 18px}.legend span{display:flex;align-items:center;gap:7px}.legend i{width:20px;height:3px;display:block}.chart-scroll{overflow-x:auto}.chart-scroll svg{width:100%;min-width:620px;height:auto;display:block}.chart-note{font-size:14px;color:var(--muted);margin-bottom:0}.table{overflow:auto;margin:18px 0;max-width:100%}table{border-collapse:collapse;width:100%;font-size:14px;line-height:1.5;font-variant-numeric:tabular-nums}th,td{padding:13px 15px;text-align:right;border-bottom:1px solid var(--line);min-width:120px}th:first-child,td:first-child{text-align:left}thead th{color:var(--muted);font-weight:650;background:#f3f6f8}tbody th{font-weight:500;min-width:190px;text-align:left}td{overflow-wrap:anywhere}details{background:white;border:1px solid var(--line);border-radius:5px;margin:12px 0}summary{font-size:16px;font-weight:650;padding:19px 22px;line-height:1.4}summary:hover{background:#f0f5f8}summary span{float:right;font-size:12px;font-weight:500;color:var(--muted);margin-left:12px}details[open]>summary{border-bottom:1px solid var(--line)}details>p,details>ul,details>.table{margin:20px 24px}details li{margin:0 0 16px;max-width:850px}.caption{font-size:15px;max-width:850px}.figure-scroll{overflow:auto;margin:0 20px}.zoom{display:block;border:0;padding:0;background:white;width:100%;min-width:780px;cursor:zoom-in}.zoom img{display:block;width:100%;height:auto}.downloads{display:flex;gap:16px;flex-wrap:wrap;font-size:13px}.downloads span{color:var(--muted)}.evidence-links{display:flex;flex-wrap:wrap;gap:12px 24px;font-size:15px}.evidence-links a{padding:5px 0}.coverage th,.coverage td{text-align:left;white-space:normal;min-width:200px}.appendix table td{min-width:130px}.appendix table th{white-space:nowrap}.appendix .table{max-height:600px}.appendix thead{position:sticky;top:0}dialog{width:96vw;max-width:none;height:94vh;max-height:none;padding:0;border:1px solid var(--line);border-radius:6px}dialog::backdrop{background:rgba(13,25,35,.75)}.dialog-head{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:16px 22px;border-bottom:1px solid var(--line)}.dialog-head h2{font-size:18px;margin:0}.dialog-head button{background:#edf2f5;border:1px solid #b3c1ca;border-radius:4px;padding:7px 14px}.dialog-body{overflow:auto;height:calc(100% - 78px);padding:16px}.dialog-body img{display:block;max-width:none;min-width:100%;width:auto;height:auto}footer{margin-top:48px;font-size:13px;color:var(--muted)}@media(max-width:900px){.results{grid-template-columns:repeat(2,minmax(0,1fr))}.findings{grid-template-columns:1fr;gap:20px}.finding{max-width:750px}}@media(max-width:600px){header{padding:28px 20px 20px}main{padding:24px 16px 40px}.nav-inner{padding:0 20px;gap:24px}.block{padding:20px 16px}.result{padding:14px}.score{font-size:28px}.score small{display:block;margin-left:0}.result h3{font-size:14px}.lead{font-size:18px}.results{gap:10px}.result dl div{display:block}.result dd{margin-top:1px}summary{padding:17px 16px}summary span{display:none}details>p,details>ul,details>.table{margin:16px}.section-title{font-size:25px}.legend{gap:10px;font-size:12px}.figure-scroll{margin:0 8px}}@media print{nav,.controls,.jump{display:none}.panel[hidden]{display:block}.panel{break-before:page}header{padding-top:0}.block,.result{break-inside:avoid}details{break-inside:avoid}body{background:white}main{padding:0}}
'''
    body=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>V3 results · 400-query analysis</title><style>{css}</style></head><body>
<header><div class="eyebrow">HC16 V3 / Kimi / Experiment results</div><h1>What did 400 queries buy?</h1><p>Four completed conditions. Compare the quality of the winning plants, the resources used to find them, and the effect of Past memory.</p><p class="snapshot">Saved snapshot: {stamp} · 400 queries <strong>per agent</strong> · One completed run per condition</p></header>
<nav aria-label="Report sections"><div class="nav-inner"><a href="#overview">Overview</a><a href="#search">Search efficiency</a><a href="#plants">Plant outcomes</a><a href="#memory">Memory & agents</a><a href="#evidence">Evidence & downloads</a></div></nav><main>
<section class="panel" id="overview"><h2 class="section-title">The swarm found the best plant.<br>The single agent used fewer resources.</h2><p class="lead">The five-agent run without Past reached <strong>$2.18B/year</strong> in modeled net value. At the same 395-query cap, the single agent without Past was ahead.</p><div class="results">{cards}</div><div class="findings"><article class="finding"><h3>+7.7% at the final endpoint</h3><p>The no-Past swarm beat the no-Past single, using 5.01× the charged queries and 2.90× the model spend.</p></article><article class="finding"><h3>−9.9% at equal queries</h3><p>At 395 team queries, the no-Past swarm trailed the single. More total search budget changes the ranking.</p></article><article class="finding"><h3>Past cost less, finished lower</h3><p>Past reduced model spend by 13% for the single and 21% for the swarm. Final plant value fell by 43% and 6%, respectively.</p></article></div><p class="callout"><strong>Read this as an exploratory comparison.</strong> The four scores use unequal total budgets. There is one completed run per condition, and recovery patches changed memory-handling code. “No Past” still includes exact sharing between swarm agents.</p><a class="jump" href="#search">Compare the resource curves →</a>{investigation}<details><summary>Read the full analysis</summary><ul>{''.join('<li>'+esc(v)+'</li>' for v in insights)}</ul></details></section>
<section class="panel" id="search"><h2 class="section-title">Compare progress at the same resource budget</h2><p class="muted">Choose a resource below. Each line tracks the best valid plant found so far; higher is better.</p><div class="block"><div class="chart-header"><h3>Best annual net value</h3><div class="controls"><label for="resource">Compare by</label><select id="resource"><option value="queries">Team queries</option><option value="equal">Team queries · first 395</option><option value="per_agent">Queries per agent · average</option><option value="backend_calls">Actual backend calls</option><option value="elapsed_s">Elapsed minutes</option><option value="usd">Model spend ($)</option><option value="input_tokens">Input tokens (millions)</option><option value="total_tokens">Total tokens (millions)</option></select></div></div><div class="legend">{legend}</div><div class="chart-scroll"><svg id="resource-chart" viewBox="0 0 960 430" role="img" aria-label="Best annual net value by cumulative team queries"></svg></div><p id="chart-note" class="chart-note" aria-live="polite"></p><noscript><p>Enable JavaScript for the resource selector. All static plots and PDFs remain available below.</p></noscript></div><details><summary>Compare resource totals</summary>{comparison(search_fields)}<p class="caption">Charged queries and actual simulator backend calls are different counters. Cached lookups can avoid a backend call; they can also revisit queries already charged.</p></details><h3>More search diagnostics</h3>{gallery([0,1,2,3,5,6,13,15])}</section>
<section class="panel" id="plants"><h2 class="section-title">What makes the winning plants valuable?</h2><p class="lead">The no-Past swarm gained $155M/year over the single: $172M less annualized cost, offset by $17M less revenue.</p><div class="block"><h3>Winning plant economics & equipment</h3>{comparison(metric_fields)}<p class="chart-note">Annualized plant cost includes utilities and capital. These modeled plant economics are separate from the dollars spent on the search.</p></div><p class="callout">The Past single recovers none of six C6 species into priced qualifying products. The material remains in terminal flows, but does not qualify for that revenue.</p><h3>Economics, product quality & physical recovery</h3>{gallery([4,7,8,9,12,14])}<h3>Winning plant layouts</h3><p class="muted">Open a layout, then click it to inspect the full-size topology.</p>{gallery([16,17,18,19])}</section>
<section class="panel" id="memory"><h2 class="section-title">Sharing was frequent. Past did not improve the endpoint.</h2><p class="lead">Both swarms converged to similar designs across their agents. Past’s early query advantage disappeared before the final checkpoint.</p><div class="findings"><article class="finding"><h3>436 vs 304 peer copies</h3><p>No-Past and Past swarms, respectively. “No Past” still shared exact peer designs and incumbents.</p></article><article class="finding"><h3>78% / 86% omitted</h3><p>Candidate memory instances omitted from prompts for the Past single / swarm under the context budget. These are repeated instances, not unique facts.</p></article><article class="finding"><h3>6.2 / 4.8 minutes</h3><p>Logged memory reads, writes and barriers for the Past single / swarm: approximately 19% / 12% of wall time.</p></article></div><p class="callout">These observations do not isolate a causal memory effect. A completed independent five-agent control and repeated trials are missing.</p>{gallery([10,11,2,15])}</section>
<section class="panel" id="evidence"><h2 class="section-title">The evidence behind the report</h2><p class="lead">{passed} of {len(checks)} data checks passed. Four completed runs and two aborted attempts are included in the saved evidence.</p><div class="block"><h3>Download the analysis</h3><div class="evidence-links"><a href="figures.pdf">All metric plots · PDF</a><a href="winning_plants.pdf">Plant layouts · PDF</a><a href="metrics.csv">Run metrics · CSV</a><a href="products.csv">Products · CSV</a><a href="checkpoints.csv">Budget checkpoints · CSV</a><a href="agents.csv">Per-agent metrics · CSV</a><a href="curves.csv">Curve data · CSV</a><a href="validation.csv">Validation checks · CSV</a><a href="report-data.json">Full evidence · JSON</a><a href="manifest.json">File hashes · JSON</a></div></div><p class="callout"><strong>$53.70 estimated model spend across all six attempts.</strong> This includes $5.51 from aborted attempts. Memory service and VM costs are unknown. Model estimates are not invoices.</p><details><summary>What is measured — and what is missing</summary><ul>{''.join('<li>'+esc(v)+'</li>' for v in notes)}</ul></details><details><summary>Coverage of the repository’s analysis guide</summary><div class="table coverage"><table><thead><tr><th>Requirement</th><th>Evidence</th><th>Coverage</th></tr></thead><tbody>{cov}</tbody></table></div><p class="caption">Sources: workplan.md, docs/RUN_ARTIFACTS.md and docs/AUTOMATIC_REPORTS.md.</p></details><h3>Detailed tables</h3><p class="muted">Raw measurements and audit fields are kept here for inspection. Wide tables scroll horizontally; CSV downloads retain full precision.</p><div class="appendix">{appendices}</div></section><footer>HC16 V3 · Saved results only · No model or simulator calls were made to build this report.</footer></main>
<dialog id="figure-dialog" aria-labelledby="dialog-title"><div class="dialog-head"><h2 id="dialog-title">Figure</h2><button id="close-figure" type="button">Close ×</button></div><div class="dialog-body"><img id="large-figure" alt=""></div></dialog>
<script id="chart-data" type="application/json">{json.dumps(dict(series=series,norm=norm)).replace('<','&lt;')}</script>
<script>__SCRIPT__</script></body></html>'''
    script=r'''
const sections=[...document.querySelectorAll('.panel')], nav=[...document.querySelectorAll('nav a')];
function showSection(){const id=location.hash.slice(1)||'overview';const active=sections.some(s=>s.id===id)?id:'overview';sections.forEach(s=>s.hidden=s.id!==active);nav.forEach(a=>{if(a.hash==='#'+active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});}
window.addEventListener('hashchange',()=>{showSection();window.scrollTo({top:0,behavior:'instant'})});showSection();
const payload=JSON.parse(document.getElementById('chart-data').textContent), svg=document.getElementById('resource-chart'), control=document.getElementById('resource');
const axis={queries:['Team queries',p=>p.queries],equal:['Team queries (same observed cap)',p=>p.queries],per_agent:['Charged queries per agent (team average)',(p,s)=>p.queries/(s.name.startsWith('5')?5:1)],backend_calls:['Actual backend calls',p=>p.backend_calls],elapsed_s:['Elapsed minutes',p=>p.elapsed_s/60],usd:['Estimated model spend ($)',p=>p.usd],input_tokens:['Input tokens (millions)',p=>p.input_tokens/1e6],total_tokens:['Total tokens (millions)',p=>(p.input_tokens+p.output_tokens)/1e6]};
function draw(){const key=control.value,[label,getX]=axis[key], xmax=key==='equal'?395:Math.max(...payload.series.flatMap(s=>s.points.map(p=>getX(p,s))));const left=66,top=28,w=865,h=325,ymax=2.4;const x=v=>left+v/xmax*w,y=v=>top+h-v/ymax*h;let content='';
for(let i=0;i<=4;i++){const v=i*.6;content+=`<line x1="${left}" x2="${left+w}" y1="${y(v)}" y2="${y(v)}" stroke="#dce4e9"/><text x="${left-12}" y="${y(v)+5}" text-anchor="end" fill="#536573" font-size="15">${v.toFixed(1)}</text>`;}
for(let i=0;i<=5;i++){const v=xmax*i/5;content+=`<text x="${x(v)}" y="${top+h+27}" text-anchor="middle" fill="#536573" font-size="15">${v.toLocaleString('en-US',{maximumFractionDigits:xmax<30?1:0})}</text>`;}
content+=`<text x="${left}" y="17" font-size="14" fill="#536573">$B / year</text><text x="${left+w/2}" y="415" text-anchor="middle" font-size="15" fill="#536573">${label}</text>`;
for(const s of payload.series){let pts=s.points.filter(p=>getX(p,s)<=xmax);if(!pts.length)continue;let last=pts[pts.length-1],d=`M ${x(getX(pts[0],s))} ${y(pts[0].reward*payload.norm/1e9)}`;for(const p of pts.slice(1))d+=` H ${x(getX(p,s))} V ${y(p.reward*payload.norm/1e9)}`;if(key==='equal'&&getX(s.points[s.points.length-1],s)>=xmax)d+=` H ${x(xmax)}`;content+=`<path d="${d}" fill="none" stroke="${s.color}" stroke-width="3" ${s.dashed?'stroke-dasharray="8 5"':''}><title>${s.name}</title></path>`;for(const p of pts){content+=`<circle cx="${x(getX(p,s))}" cy="${y(p.reward*payload.norm/1e9)}" r="4" fill="${s.color}" fill-opacity=".01"><title>${s.name}: $${(p.reward*payload.norm/1e9).toFixed(3)}B/year at ${getX(p,s).toLocaleString('en-US',{maximumFractionDigits:2})} ${label}</title></circle>`;}}
svg.innerHTML=content;svg.setAttribute('aria-label','Best annual net value by '+label);document.getElementById('chart-note').textContent=key==='equal'?'All four runs are shown through 395 team queries, the last observed query count of the shortest run. These are prefixes of runs announced with a 400-query allowance per agent.':key==='per_agent'?'Five-agent team queries are divided by five. This compares average usage against the 400-query per-agent allowance, not equal total work.':'Lines stop at each observed endpoint. A five-agent run can use up to 2,000 team queries; a single-agent run can use up to 400. Past runs use dashed lines. Hover over a curve point for exact values.';
}
control.addEventListener('change',draw);draw();
const dialog=document.getElementById('figure-dialog'), large=document.getElementById('large-figure');document.querySelectorAll('.zoom').forEach(b=>b.addEventListener('click',()=>{large.src=b.querySelector('img').src;large.alt=b.dataset.title;document.getElementById('dialog-title').textContent=b.dataset.title;dialog.showModal()}));document.getElementById('close-figure').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
'''
    return body.replace('__SCRIPT__',script)
